package com.dot.gallery

/**
 * `BuildConfig` replacement for the KMP split, in the same package as the old
 * AGP-generated class so call sites migrate unchanged.
 *
 * Global flags are compile-time constants generated by BuildKonfig for
 * commonMain. Variant-scoped values (applicationId, versionName,
 * CONTENT_AUTHORITY, per-build-type toggles) cannot be constants in a library —
 * the entry module (androidApp's GalleryApp) pushes them in before the
 * component graph is created, so they must only be read at runtime.
 */
object BuildConfig {

    // Variant-scoped — populated by the platform entry point at startup.
    var VERSION_NAME: String = ""
    var VERSION_CODE: Int = 0
    var APPLICATION_ID: String = ""
    var BUILD_TYPE: String = ""
    var FLAVOR: String = ""
    var CONTENT_AUTHORITY: String = ""
    var ALLOW_INSECURE_TLS: Boolean = false
    var ALLOW_ALL_FILES_ACCESS: Boolean = false
    var ENABLE_INDEXING: Boolean = false
    var ML_MODELS_BUNDLED: Boolean = false

    // Global flags — identical for every app variant, so they can be
    // compile-time constants generated by BuildKonfig.
    val OFFLINE_MODE: Boolean = BuildKonfig.OFFLINE_MODE
    val MAPS_ENABLED: Boolean = BuildKonfig.MAPS_ENABLED
    val IMMICH_ENABLED: Boolean = BuildKonfig.IMMICH_ENABLED
    val PHOTOPRISM_ENABLED: Boolean = BuildKonfig.PHOTOPRISM_ENABLED
    val OWNCLOUD_ENABLED: Boolean = BuildKonfig.OWNCLOUD_ENABLED
    val NEXTCLOUD_ENABLED: Boolean = BuildKonfig.NEXTCLOUD_ENABLED
    val WEBDAV_ENABLED: Boolean = BuildKonfig.WEBDAV_ENABLED
    val SMB_ENABLED: Boolean = BuildKonfig.SMB_ENABLED
    val NFS_ENABLED: Boolean = BuildKonfig.NFS_ENABLED
    val CARTO_BASEMAP_KEY: String = BuildKonfig.CARTO_BASEMAP_KEY
}
